import { Injectable } from "@nestjs/common";
import type { LanguageCollectionDto } from "#/modules/reference/schema/dto/language-collection.dto.ts";
import type { ReferenceWindowDto } from "#/modules/reference/schema/dto/reference-window.dto.ts";
import { ListLanguagesUseCase } from "#/modules/reference/features/languages/use-cases/list-languages.repository.ts";

/**
 * The Languages contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class ReferenceLanguagesService {
  abstract listLanguages(input: ReferenceWindowDto): Promise<LanguageCollectionDto>;
}

@Injectable()
export class ReferenceLanguagesServiceImpl extends ReferenceLanguagesService {
  constructor(private readonly listLanguagesUseCase: ListLanguagesUseCase) {
    super();
  }

  listLanguages(input: ReferenceWindowDto): Promise<LanguageCollectionDto> {
    return this.listLanguagesUseCase.execute(input);
  }
}
